import { describe, it, expect, vi } from "vitest";
import { render, screen, fireEvent } from "@testing-library/react";
import { ProjectRow } from "./ProjectsList";

const mockProject = {
  id: "PVT_1",
  number: 7,
  title: "My App",
  shortDescription: "desc",
  url: "https://github.com/x",
  closed: false,
  updatedAt: new Date().toISOString(),
  items: { totalCount: 3, nodes: [
    { content: { state: "OPEN" } },
    { content: { state: "CLOSED" } },
    { content: { state: "CLOSED" } },
  ] },
  repositories: { nodes: [{ nameWithOwner: "o/a" }] },
};

function row(over: Partial<Parameters<typeof ProjectRow>[0]> = {}) {
  return (
    <ProjectRow
      p={mockProject}
      running={0}
      paused={0}
      onPlan={() => {}}
      onBoard={() => {}}
      onDelete={() => {}}
      menuOpenId={mockProject.id}
      setMenuOpenId={() => {}}
      {...over}
    />
  );
}

// Regression guard: the row's ⋯ menu items must reach their handlers. The bug
// was an eager document-mousedown handler that closed the menu before the item's
// click fired, so delete/board never ran.
describe("ProjectRow", () => {
  it("clicking the row opens planning (#499)", () => {
    const onPlan = vi.fn();
    render(row({ onPlan }));
    fireEvent.click(screen.getByText("open planning →"));
    expect(onPlan).toHaveBeenCalledWith(mockProject);
  });

  it("shows the live fleet pill when agents are running (#499)", () => {
    render(row({ running: 2, paused: 1 }));
    expect(screen.getByText(/2 agents running/)).toBeTruthy();
    expect(screen.getByText(/1 paused/)).toBeTruthy();
  });

  it("shows open count + closed-fraction progress (#499)", () => {
    render(row());
    // 1 open of 3 items (2 closed) → 67%.
    expect(screen.getByText("1")).toBeTruthy(); // open count
    expect(screen.getByText("67%")).toBeTruthy();
  });

  it("calls onBoard when 'open board on GitHub' is clicked", () => {
    const onBoard = vi.fn();
    render(row({ onBoard }));
    fireEvent.click(screen.getByText("open board on GitHub"));
    expect(onBoard).toHaveBeenCalledWith(mockProject);
  });

  it("calls onDelete when 'delete project' is clicked with the menu open", () => {
    const onDelete = vi.fn();
    render(row({ onDelete }));
    fireEvent.click(screen.getByText("delete project"));
    expect(onDelete).toHaveBeenCalledWith(mockProject);
  });

  it("does not render the menu when this row isn't the open one", () => {
    render(row({ menuOpenId: null }));
    expect(screen.queryByText("delete project")).not.toBeInTheDocument();
  });
});

import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, screen, fireEvent, waitFor } from "@testing-library/react";
import { invoke } from "@tauri-apps/api/core";
import { ProjectsList } from "./ProjectsList";
import { useAppStore } from "@/store";

// #1216 — the published-project delete is a Keep-vs-Delete modal:
//   • "Keep the app" (default/safe): local cleanup only, NO GitHub DELETE_MUTATION.
//   • "Delete everything": local cleanup PLUS the GitHub project DELETE_MUTATION, behind an
//     explicit second confirm.
// And the draft ✕ now opens a confirmation modal before destroying the folder.

const PUBLISHED = {
  id: "PVT_node_1",
  number: 9,
  title: "Shipped App",
  shortDescription: "a published project",
  url: "https://github.com/o/shipped",
  closed: false,
  updatedAt: new Date().toISOString(),
  items: { totalCount: 0, nodes: [] },
  repositories: { nodes: [{ nameWithOwner: "o/shipped" }] },
};

/** Route the mocked Tauri `invoke`, recording which GraphQL queries were sent so a test can assert
 *  whether the DELETE_MUTATION ran. */
function routeInvoke() {
  const graphqlCalls: Array<{ query: string; variables: unknown }> = [];
  const repoDeleteCalls: string[] = [];
  vi.mocked(invoke).mockImplementation(((cmd: string, args?: Record<string, unknown>) => {
    if (cmd === "list_local_projects") return Promise.resolve([]);
    if (cmd === "github_delete") { repoDeleteCalls.push(String(args?.path ?? "")); return Promise.resolve(null); }
    if (cmd === "github_graphql") {
      const query = String(args?.query ?? "");
      // The initial PROJECTS_QUERY returns the published project; record + answer DELETE separately.
      if (query.includes("deleteProjectV2")) {
        graphqlCalls.push({ query, variables: args?.variables });
        return Promise.resolve({ deleteProjectV2: { projectV2: { id: PUBLISHED.id } } });
      }
      graphqlCalls.push({ query, variables: args?.variables });
      return Promise.resolve({ viewer: { projectsV2: { nodes: [PUBLISHED] } } });
    }
    if (cmd === "delete_project_dir") return Promise.resolve(null);
    return Promise.resolve(null);
  }) as unknown as typeof invoke);
  return {
    deleteMutationRan: () => graphqlCalls.some(c => c.query.includes("deleteProjectV2")),
    deleteDirCalled: () => vi.mocked(invoke).mock.calls.some(c => c[0] === "delete_project_dir"),
    repoDeletes: () => repoDeleteCalls,
  };
}

/** Open the ⋯ menu on the published row and click "delete project" to open the Keep-vs-Delete modal.
 *  Several elements carry the "More options" title (each row + each blueprint card); the project
 *  row's is the first. */
function openDeleteModal() {
  fireEvent.click(screen.getAllByTitle("More options")[0]);
  fireEvent.click(screen.getByText("delete project"));
}

describe("ProjectsList — published delete (Keep vs Delete, #1216)", () => {
  beforeEach(() => {
    vi.mocked(invoke).mockReset();
    useAppStore.setState({
      activeWorkspace: "projects",
      githubToken: "gho_test",
      localDraftProjects: {},
      hiddenProjectIds: [],
    });
  });

  it("offers both Keep and Delete-everything actions plus cancel", async () => {
    routeInvoke();
    render(<ProjectsList />);
    await screen.findByText("Shipped App");
    openDeleteModal();
    expect(screen.getByText(/Keep the app/i)).toBeTruthy();
    expect(screen.getAllByText(/Delete everything/i).length).toBeGreaterThan(0);
    // The destructive copy clarifies repos/code are NOT deleted by the GitHub project delete.
    expect(screen.getByText(/board, milestones, issues, and repos stay intact/i)).toBeTruthy();
    expect(screen.getByText(/repos and their code are not deleted/i)).toBeTruthy();
    expect(screen.getByRole("button", { name: /cancel/i })).toBeTruthy();
  });

  it("Delete everything + repositories deletes each repo, the board, and the local copy", async () => {
    const r = routeInvoke();
    render(<ProjectsList />);
    await screen.findByText("Shipped App");
    openDeleteModal();
    // The 3rd, most-destructive option arms its own confirm…
    fireEvent.click(screen.getByText(/permanently deletes the linked GitHub repositories/i));
    // …then confirm.
    fireEvent.click(screen.getByRole("button", { name: /delete everything \+ repos/i }));
    // Each linked repo is DELETEd, then the board, then the local copy.
    await waitFor(() => expect(r.repoDeletes()).toContain("repos/o/shipped"));
    expect(r.deleteMutationRan()).toBe(true);
    expect(r.deleteDirCalled()).toBe(true);
  });

  it("Keep does local cleanup and does NOT run the GitHub DELETE_MUTATION", async () => {
    const r = routeInvoke();
    render(<ProjectsList />);
    await screen.findByText("Shipped App");
    openDeleteModal();
    fireEvent.click(screen.getByText(/Keep the app/i));
    await waitFor(() => expect(screen.queryByText("Shipped App")).toBeNull());
    expect(r.deleteDirCalled()).toBe(true);
    expect(r.deleteMutationRan()).toBe(false);
    // Persisted dismissal so the next GitHub sync doesn't re-list it.
    expect(useAppStore.getState().hiddenProjectIds).toContain(PUBLISHED.id);
  });

  it("Delete everything runs BOTH local cleanup and the GitHub DELETE_MUTATION (behind a 2nd confirm)", async () => {
    const r = routeInvoke();
    render(<ProjectsList />);
    await screen.findByText("Shipped App");
    openDeleteModal();
    // Arm the destructive path (the choice-view button, identified by its description) — this alone
    // must NOT delete yet.
    fireEvent.click(screen.getByText(/Removes the local copy AND deletes the GitHub project board/i));
    expect(r.deleteMutationRan()).toBe(false);
    // The explicit second confirm (the danger button in the confirm view).
    fireEvent.click(screen.getByRole("button", { name: /delete everything/i }));
    await waitFor(() => expect(screen.queryByText("Shipped App")).toBeNull());
    expect(r.deleteDirCalled()).toBe(true);
    expect(r.deleteMutationRan()).toBe(true);
    expect(useAppStore.getState().hiddenProjectIds).toContain(PUBLISHED.id);
  });

  it("arming Delete-everything then choosing Back returns to the choice without deleting", async () => {
    const r = routeInvoke();
    render(<ProjectsList />);
    await screen.findByText("Shipped App");
    openDeleteModal();
    fireEvent.click(screen.getByText(/Removes the local copy AND deletes the GitHub project board/i));
    fireEvent.click(screen.getByRole("button", { name: /^back$/i }));
    // Back at the choice screen: Keep is offered again, nothing deleted.
    expect(screen.getByText(/Keep the app/i)).toBeTruthy();
    expect(r.deleteMutationRan()).toBe(false);
    expect(r.deleteDirCalled()).toBe(false);
  });
});

describe("ProjectsList — draft delete now requires confirmation (#1216)", () => {
  beforeEach(() => {
    vi.mocked(invoke).mockReset();
    useAppStore.setState({
      activeWorkspace: "projects",
      githubToken: "gho_test",
      localDraftProjects: { my_draft: { title: "My Draft", pitch: "a pitch", createdAt: 1 } },
      hiddenProjectIds: [],
    });
  });

  it("clicking the chip ✕ opens a confirmation and does not delete until confirmed", async () => {
    const calls: string[] = [];
    vi.mocked(invoke).mockImplementation(((cmd: string) => {
      calls.push(cmd);
      if (cmd === "list_local_projects") return Promise.resolve([]);
      if (cmd === "github_graphql") return Promise.resolve({ viewer: { projectsV2: { nodes: [] } } });
      return Promise.resolve(null);
    }) as unknown as typeof invoke);

    render(<ProjectsList />);
    await screen.findByText("My Draft");
    // The card's ⋯ menu (#3802 rebuilt the tab in the Skills-tab style, so the destructive action
    // moved off an inline chip ✕ and behind the menu) — opens the confirm modal, must NOT delete
    // the folder yet. EXACT names: the card is itself a role=button whose accessible name
    // concatenates its subtree, so a loose /delete draft/i also matches the card.
    fireEvent.click(screen.getByTitle("More options"));
    fireEvent.click(screen.getByRole("button", { name: "delete draft" }));   // menu item
    expect(screen.getByText("Delete draft?")).toBeTruthy();
    expect(calls.includes("delete_project_dir")).toBe(false);
    // "My Draft" now appears both on the card and in the modal's <b>; still present (not deleted).
    expect(screen.getAllByText("My Draft").length).toBeGreaterThan(0);

    // Confirm — now it deletes.
    fireEvent.click(screen.getByRole("button", { name: "delete draft" }));   // modal confirm
    await waitFor(() => expect(screen.queryByText("My Draft")).toBeNull());
    expect(calls.includes("delete_project_dir")).toBe(true);
    expect(useAppStore.getState().localDraftProjects.my_draft).toBeUndefined();
  });

  it("cancelling the draft confirmation keeps the draft and deletes nothing", async () => {
    const calls: string[] = [];
    vi.mocked(invoke).mockImplementation(((cmd: string) => {
      calls.push(cmd);
      if (cmd === "list_local_projects") return Promise.resolve([]);
      if (cmd === "github_graphql") return Promise.resolve({ viewer: { projectsV2: { nodes: [] } } });
      return Promise.resolve(null);
    }) as unknown as typeof invoke);

    render(<ProjectsList />);
    await screen.findByText("My Draft");
    fireEvent.click(screen.getByTitle("More options"));
    fireEvent.click(screen.getByRole("button", { name: "delete draft" }));   // menu item
    fireEvent.click(screen.getByRole("button", { name: /cancel/i }));
    await waitFor(() => expect(screen.queryByText("Delete draft?")).toBeNull());
    expect(calls.includes("delete_project_dir")).toBe(false);
    expect(screen.getByText("My Draft")).toBeTruthy();
    expect(useAppStore.getState().localDraftProjects.my_draft).toBeTruthy();
  });
});

import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, screen, fireEvent, waitFor } from "@testing-library/react";
import { invoke } from "@tauri-apps/api/core";
import { ProjectsList } from "./ProjectsList";
import { useAppStore } from "@/store";

// Repro for the draft-delete crash (#…): deleting a "draft" project
// card must remove the card and never throw — regardless of what `list_local_projects`
// returns (incl. a non-array) or whether the folder delete succeeds.

function routeInvoke(opts: { localProjects?: unknown; deleteRejects?: boolean } = {}) {
  vi.mocked(invoke).mockImplementation(((cmd: string) => {
    if (cmd === "list_local_projects") return Promise.resolve(opts.localProjects ?? []);
    if (cmd === "github_graphql") return Promise.resolve({ viewer: { projectsV2: { nodes: [] } } });
    if (cmd === "delete_project_dir") {
      return opts.deleteRejects ? Promise.reject("folder locked") : Promise.resolve(null);
    }
    return Promise.resolve(null);
  }) as unknown as typeof invoke);
}

// The Projects tab was rebuilt in the Skills-tab style (#3802): a draft is a CARD whose
// destructive action lives behind the ⋯ menu, not an inline ✕ on a chip. So the delete is a
// three-step drive — open the menu, pick "delete draft", then confirm in the modal (#1216).
// The menu item and the modal button never coexist (picking the item closes the menu and opens
// the modal), so the same query resolves unambiguously at each step.
function clickDeleteDraft() {
  fireEvent.click(screen.getByTitle("More options"));
  // EXACT name, not a regex: the card itself is a role=button whose accessible name concatenates
  // its whole subtree, so a loose /delete draft/i also matches the card while the menu is open.
  fireEvent.click(screen.getByRole("button", { name: "delete draft" }));   // menu item
  fireEvent.click(screen.getByRole("button", { name: "delete draft" }));   // modal confirm
}

describe("ProjectsList — draft delete", () => {
  beforeEach(() => {
    vi.mocked(invoke).mockReset();
    useAppStore.setState({
      activeWorkspace: "projects",
      githubToken: "gho_test",
      localDraftProjects: { my_draft: { title: "My Draft", pitch: "a pitch", createdAt: 1 } },
    });
  });

  it("removes the draft card when delete is confirmed (folder delete ok)", async () => {
    routeInvoke({ localProjects: [] });
    render(<ProjectsList />);
    await screen.findByText("My Draft");
    clickDeleteDraft();
    await waitFor(() => expect(screen.queryByText("My Draft")).toBeNull());
    expect(useAppStore.getState().localDraftProjects.my_draft).toBeUndefined();
  });

  it("surfaces an error (no crash) when the folder delete fails", async () => {
    routeInvoke({ localProjects: [], deleteRejects: true });
    render(<ProjectsList />);
    await screen.findByText("My Draft");
    clickDeleteDraft();
    // The card stays and an inline error appears; the app does not crash.
    await waitFor(() => expect(screen.getByText(/Couldn't delete the folder/)).toBeTruthy());
    expect(screen.getByText("My Draft")).toBeTruthy();
  });

  it("does not crash when list_local_projects returns a non-array", async () => {
    routeInvoke({ localProjects: null });
    render(<ProjectsList />);
    // The draft from the store still renders; the null on-disk list must not throw.
    await screen.findByText("My Draft");
    clickDeleteDraft();
    await waitFor(() => expect(screen.queryByText("My Draft")).toBeNull());
  });
});

import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, screen, fireEvent, waitFor } from "@testing-library/react";
import { invoke } from "@tauri-apps/api/core";
import { ProjectsList } from "./ProjectsList";
import { useAppStore } from "@/store";
import { type Blueprint } from "../stages/blueprints";

// The create flow (#3802): `+ New project` opens the full-pane ProjectSetupPage (name + blueprint)
// BETWEEN the list and the planner; the chosen blueprint is bound AT CREATION. These tests drive
// that flow end-to-end through <ProjectsList /> (the setup page's own unit tests live alongside it).

function bp(over: Partial<Blueprint>): Blueprint {
  return { id: "x", name: "X", desc: "", sections: [], ...over };
}

function routeInvoke() {
  vi.mocked(invoke).mockImplementation(((cmd: string) => {
    if (cmd === "list_local_projects") return Promise.resolve([]);
    if (cmd === "github_graphql") return Promise.resolve({ viewer: { projectsV2: { nodes: [] } } });
    return Promise.resolve(null);
  }) as unknown as typeof invoke);
}

/** Click `+ New project` (there can be two — the header + the empty-state — so take the first).
 *  For the same reason every WAIT for the button uses findAllByRole: the singular query throws
 *  on multiple matches, and the empty-state CTA (#3802) made a second one routine. */
function openSetup() {
  fireEvent.click(screen.getAllByRole("button", { name: "+ New project" })[0]);
}

describe("ProjectsList — create flow (setup page)", () => {
  beforeEach(() => {
    vi.mocked(invoke).mockReset();
    routeInvoke();
    useAppStore.setState({
      activeWorkspace: "projects",
      githubToken: "gho_test",
      localDraftProjects: {},
      projectBlueprintId: {},
      blueprints: [],
      // Cleared per-test: the creating tests above set it, and the back-out test asserts nothing
      // was created — without this reset that assertion reads the PREVIOUS test's key.
      planningSessionKey: "",
    });
  });

  it("opens the setup page and lists ALL blueprints — saved AND built-in (#blueprints)", async () => {
    useAppStore.setState({
      blueprints: [
        bp({ id: "mine", name: "My Greenfield", origin: "local" }),
        bp({ id: "stock", name: "Stock Built-in", origin: "built-in" }),
      ],
    });
    render(<ProjectsList />);
    await screen.findAllByRole("button", { name: "+ New project" });
    openSetup();
    expect(await screen.findByText("New project")).toBeTruthy();
    expect(screen.getByText("My Greenfield")).toBeTruthy();
    expect(screen.getByText("Stock Built-in")).toBeTruthy(); // built-ins are surfaced here too
  });

  it("binds the ACTIVE blueprint AT CREATION — not on a later open (#988)", async () => {
    // Regression: opening a project used to adopt the transient global selection. The binding must
    // be captured once, when the project is created, from whatever is selected then.
    useAppStore.setState({
      blueprints: [bp({ id: "fullstack", name: "Full-stack", origin: "local" })],
      activeBlueprintId: "fullstack",
    });
    render(<ProjectsList />);
    await screen.findAllByRole("button", { name: "+ New project" });
    openSetup();
    fireEvent.change(await screen.findByLabelText("Project name"), { target: { value: "My New App" } });
    fireEvent.click(screen.getByText("start planning →"));
    await waitFor(() => {
      const s = useAppStore.getState();
      // #2409 (supersedes the #1741 minted id): the workspace key IS the name-derived slug,
      // frozen at creation — `projectSlug("My New App")`.
      expect(s.planningSessionKey).toBe("my-new-app");
      // …and the blueprint is bound to the selection at creation, under that same stable key.
      expect(s.projectBlueprintId[s.planningSessionKey]).toBe("fullstack");
    });
  });

  it("binds a NEWLY-SELECTED blueprint (not the active default) at creation", async () => {
    useAppStore.setState({
      blueprints: [
        bp({ id: "default", name: "Default", origin: "built-in" }),
        bp({ id: "api", name: "API Service", origin: "local" }),
      ],
      activeBlueprintId: "default",
    });
    render(<ProjectsList />);
    await screen.findAllByRole("button", { name: "+ New project" });
    openSetup();
    fireEvent.click(await screen.findByText("API Service"));   // select a different blueprint
    fireEvent.change(screen.getByLabelText("Project name"), { target: { value: "Widgets" } });
    fireEvent.click(screen.getByText("start planning →"));
    await waitFor(() => {
      const s = useAppStore.getState();
      expect(s.planningSessionKey).toBe("widgets");
      expect(s.projectBlueprintId[s.planningSessionKey]).toBe("api");
    });
  });

  it("returns to the list (does not create) when the user backs out", async () => {
    useAppStore.setState({
      blueprints: [bp({ id: "mine", name: "My Greenfield", origin: "local" })],
    });
    render(<ProjectsList />);
    await screen.findAllByRole("button", { name: "+ New project" });
    openSetup();
    fireEvent.click(await screen.findByLabelText("Back to projects"));
    // Back on the list; no project was created.
    await screen.findAllByRole("button", { name: "+ New project" });
    expect(useAppStore.getState().planningSessionKey).toBeFalsy();
  });
});

// #2998 — a draft's durable projects.db state splits DRAFTS (a bare `drafted`/absent idea) from
// IN PROGRESS (a `created`/`planning` project whose hub + plan already exist).
//
// #3802 rebuilt the Projects tab in the Skills-tab style, so that split is no longer expressed as
// two chip ROWS under counted headers ("2 in progress" / "1 draft") — every project is now a card
// in ONE grid, carrying its own status chip, with the same distinction available as a status facet.
// The GUARANTEE is unchanged and still worth a test at this level: the async `bsc project db list`
// rows have to reach the rendered card as the right status. `projectsFilter.test.ts` covers the
// pure derivation; this covers the wiring — the DB read, the merge with the store draft map, and
// what actually lands on screen.
import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, screen, within, waitFor } from "@testing-library/react";
import { invoke } from "@tauri-apps/api/core";
import { ProjectsList } from "./ProjectsList";
import { useAppStore } from "@/store";
import type { DbProject } from "./projectsDbBridge";

// projects.db rows: `building_app` is CREATED, `mid_plan` is PLANNING → both are "in progress".
// `bare_idea` is intentionally absent from the DB → a bare draft.
const DB_ROWS: DbProject[] = [
  { key: "building_app", title: "Building App", pitch: "", blueprint: null, category: null, state: "created", createdAt: 0, updatedAt: 0 },
  { key: "mid_plan", title: "Mid Plan", pitch: "", blueprint: null, category: null, state: "planning", createdAt: 0, updatedAt: 0 },
];

function routeInvoke(dbRows: DbProject[]) {
  vi.mocked(invoke).mockImplementation(((cmd: string, args?: Record<string, unknown>) => {
    if (cmd === "list_local_projects") return Promise.resolve([]);
    if (cmd === "github_graphql") return Promise.resolve({ viewer: { projectsV2: { nodes: [] } } });
    if (cmd === "bsc") {
      const a = (args as { args?: string[] } | undefined)?.args ?? [];
      // `bsc project db list --json` returns the raw stdout STRING the bridge JSON-parses.
      if (a[0] === "project" && a[1] === "db" && a[2] === "list") return Promise.resolve(JSON.stringify(dbRows));
      return Promise.resolve("");
    }
    return Promise.resolve(null);
  }) as unknown as typeof invoke);
}

/** The status chip text on the card carrying `title` — the per-project surface that replaced the
 *  group headers. Scoped to the card so a chip on a sibling card can't satisfy the assertion. */
function statusOf(title: string): string {
  const card = screen.getByText(title).closest(".project-card, .project-row");
  expect(card, `a card for ${title}`).toBeTruthy();
  const chip = within(card as HTMLElement).getByText(/^(in progress|draft|active|shipped)$/);
  return chip.textContent ?? "";
}

describe("ProjectsList — Drafts vs In progress split (#2998, per-card since #3802)", () => {
  beforeEach(() => {
    vi.mocked(invoke).mockReset();
    useAppStore.setState({
      activeWorkspace: "projects",
      githubToken: "gho_test",
      hiddenProjectIds: [],
      githubState: null,
      // `bare_idea` (no DB row) + `building_app` (DB row = created) come from the store draft map;
      // `mid_plan` (DB row = planning) is surfaced by mergeDbDrafts.
      localDraftProjects: {
        bare_idea: { title: "Bare Idea", pitch: "", createdAt: 3 },
        building_app: { title: "Building App", pitch: "", createdAt: 2 },
      },
    });
  });

  it("marks created/planning projects in-progress and a bare idea a draft", async () => {
    routeInvoke(DB_ROWS);
    render(<ProjectsList />);

    // `mid_plan` exists ONLY in the DB, so its card appearing proves the async read + merge ran.
    await screen.findByText("Mid Plan");

    await waitFor(() => expect(statusOf("Building App")).toBe("in progress")); // DB state = created
    expect(statusOf("Mid Plan")).toBe("in progress");                          // DB state = planning
    expect(statusOf("Bare Idea")).toBe("draft");                               // no DB row
  });

  it("leaves every draft a draft when the DB has no rows", async () => {
    routeInvoke([]);
    render(<ProjectsList />);

    await screen.findByText("Bare Idea");
    // Both store-map drafts stay bare; nothing is promoted to in-progress without a DB state.
    expect(statusOf("Bare Idea")).toBe("draft");
    expect(statusOf("Building App")).toBe("draft");
    expect(screen.queryByText("Mid Plan")).toBeNull();
  });
});

import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, screen, fireEvent, waitFor } from "@testing-library/react";
import { invoke } from "@tauri-apps/api/core";
import { ProjectsList } from "./ProjectsList";
import { useAppStore } from "@/store";
import { DEFAULT_MAX_AGE_SECS } from "@/shared/lib/github/github";

// #2447 — the projects-list board read used to `invoke("github_graphql")` with NO `maxAgeSecs`,
// so every tab re-open re-POSTed the full projectsV2 scan. It now goes through `githubGraphql`
// (backend TTL cache); the manual "↻ sync" button is the explicit-refresh affordance and must
// bypass the window with `force: true`.

/** All github_graphql payloads the component sent, in order. */
function graphqlCalls(): Record<string, unknown>[] {
  return vi.mocked(invoke).mock.calls
    .filter(([cmd]) => cmd === "github_graphql")
    .map(([, args]) => args as Record<string, unknown>);
}

describe("ProjectsList — board reads hit the TTL cache (#2447)", () => {
  beforeEach(() => {
    vi.mocked(invoke).mockReset();
    vi.mocked(invoke).mockImplementation(((cmd: string) => {
      if (cmd === "list_local_projects") return Promise.resolve([]);
      if (cmd === "github_graphql") return Promise.resolve({ viewer: { projectsV2: { nodes: [] } } });
      return Promise.resolve(null);
    }) as unknown as typeof invoke);
    useAppStore.setState({ activeWorkspace: "projects", githubToken: "gho_test" });
  });

  it("the tab-open fetch carries the default TTL (cached within the window)", async () => {
    render(<ProjectsList />);
    await waitFor(() => expect(graphqlCalls().length).toBeGreaterThan(0));
    expect(graphqlCalls()[0]).toMatchObject({
      token: "gho_test",
      maxAgeSecs: DEFAULT_MAX_AGE_SECS,
    });
    expect(graphqlCalls()[0].force).toBeUndefined();
  });

  it("the manual ↻ sync bypasses the TTL with force: true", async () => {
    render(<ProjectsList />);
    // Wait for the initial fetch to settle so the sync button is enabled again.
    await waitFor(() => expect(screen.getByRole("button", { name: /sync/i })).not.toBeDisabled());
    fireEvent.click(screen.getByRole("button", { name: /sync/i }));
    await waitFor(() => expect(graphqlCalls().length).toBeGreaterThan(1));
    const calls = graphqlCalls();
    expect(calls[calls.length - 1]).toMatchObject({ force: true });
  });
});

// #2445 — logged out of GitHub, published projects must still appear in the Projects page: the
// published column renders the LOCAL inventory (hubs carrying `.published` + `.title`), and a
// fetched GitHub board overlays its hub once the query returns. (The local-only "not synced" hint that
// shipped with #2445 was removed in #3818, and the header's connection state that replaced it was itself
// removed in #3854 — the header leads with search now. Neither is asserted here; the point is the ROWS.)
import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, screen, waitFor } from "@testing-library/react";
import { invoke } from "@tauri-apps/api/core";
import { ProjectsList } from "./ProjectsList";
import { useAppStore } from "@/store";
import type { GhProject } from "./published/publishedModel";
import type { MinimalGhProject } from "@/shared/lib/github/githubState";

const LOCAL_PUBLISHED = { key: "acme-crm", title: "Acme CRM", hasPlan: true, updatedAt: 5, published: true };

const GH_ACME: GhProject = {
  id: "PVT_1", number: 1, title: "Acme CRM", shortDescription: null, url: "", closed: false,
  updatedAt: new Date().toISOString(), items: { totalCount: 0, nodes: [] }, repositories: { nodes: [] },
};

function routeInvoke(ghNodes: GhProject[]) {
  vi.mocked(invoke).mockImplementation(((cmd: string) => {
    if (cmd === "list_local_projects") return Promise.resolve([LOCAL_PUBLISHED]);
    if (cmd === "github_graphql") return Promise.resolve({ viewer: { projectsV2: { nodes: ghNodes } } });
    return Promise.resolve(null);
  }) as unknown as typeof invoke);
}

describe("ProjectsList — local published inventory (#2445)", () => {
  beforeEach(() => {
    vi.mocked(invoke).mockReset();
    useAppStore.setState({ activeWorkspace: "projects", localDraftProjects: {}, hiddenProjectIds: [], githubState: null });
  });

  it("LOGGED OUT: a local published hub renders in the published column", async () => {
    useAppStore.setState({ githubToken: "" });
    routeInvoke([]);
    render(<ProjectsList />);

    // The hub renders from the local inventory — title from `.title`, key as the identity.
    await screen.findByText("Acme CRM");
    expect(screen.getByText("acme-crm")).toBeTruthy();
    // Logged out and never synced, no staleness hint renders at all (#3818).
    expect(screen.queryByText(/synced/i)).toBeNull();
    // A published hub is NOT a draft — no draft chip / delete affordance for it.
    expect(screen.queryByTitle("delete draft")).toBeNull();
  });

  it("LOGGED IN: the fetched board OVERLAYS the hub — one row", async () => {
    useAppStore.setState({ githubToken: "gho_test" });
    routeInvoke([GH_ACME]);
    render(<ProjectsList />);

    await screen.findByText("Acme CRM");
    // The GitHub sync landed and its record matched the hub key, so the local row dropped out:
    // exactly ONE "Acme CRM" (the full board ProjectRow).
    await waitFor(() => expect(screen.getAllByText("Acme CRM")).toHaveLength(1));
    expect(screen.queryByText("acme-crm")).toBeNull(); // the local row's key line is gone too
    expect(screen.queryByText(/last synced/i)).toBeNull(); // live data — no staleness hint (#2446)
  });
});

// #2446 — the persisted last-known board state renders as a stale-marked overlay: logged out (or
// pre-refresh), a persisted record overlays its local hub as a full board row with a "last synced
// <age>" hint — but a record whose hub was deleted is NOT resurrected.
describe("ProjectsList — persisted GitHub-state overlay (#2446)", () => {
  const record = (title: string): MinimalGhProject => ({
    id: `PVT_${title}`, number: 3, title, shortDescription: null, url: "", closed: false,
    updatedAt: new Date().toISOString(), itemsTotalCount: 4, openCount: 3, closedCount: 1, repos: ["o/r"],
  });

  beforeEach(() => {
    vi.mocked(invoke).mockReset();
    useAppStore.setState({
      activeWorkspace: "projects", localDraftProjects: {}, hiddenProjectIds: [],
      githubToken: "", githubState: null,
    });
  });

  it("LOGGED OUT: a persisted record overlays its hub as a board row with the last-synced hint", async () => {
    routeInvoke([]); // no live GitHub — only list_local_projects answers
    useAppStore.setState({
      githubState: {
        records: [record("Acme CRM"), record("Ghost App")], // Ghost App's hub was deleted
        fetchedAt: Date.now() - 2 * 3_600_000,
      },
    });
    render(<ProjectsList />);

    // The record overlays the hub: the richer board row renders (title only — the plain local
    // row's key line is gone) …
    await screen.findByText("Acme CRM");
    await waitFor(() => expect(screen.queryByText("acme-crm")).toBeNull());
    // … under the stale-marked hint, which is the only hint the column renders (#3818).
    expect(screen.getByText(/last synced 2h ago/i)).toBeTruthy();
    // The don't-resurrect rule: a persisted record with no local hub does NOT render.
    expect(screen.queryByText("Ghost App")).toBeNull();
  });

  it("LOGGED IN: the live fetch takes precedence over the persisted overlay (no staleness hint)", async () => {
    useAppStore.setState({
      githubToken: "gho_test",
      githubState: { records: [record("Acme CRM")], fetchedAt: Date.now() - 3_600_000 },
    });
    routeInvoke([GH_ACME]);
    render(<ProjectsList />);

    await screen.findByText("Acme CRM");
    // Once the live sync lands, the stale hint drops and exactly one (live) row renders.
    await waitFor(() => expect(screen.queryByText(/last synced/i)).toBeNull());
    expect(screen.getAllByText("Acme CRM")).toHaveLength(1);
    // The fresh fetch overwrote the persisted records + fetchedAt.
    expect(useAppStore.getState().githubState!.records[0].id).toBe("PVT_1");
  });

  it("BACKFILL (#2467): a matched hub with a DERIVED title gets the board title persisted; a user-titled hub is left alone", async () => {
    useAppStore.setState({ githubToken: "gho_test" });
    const calls: Array<{ cmd: string; args?: Record<string, unknown> }> = [];
    vi.mocked(invoke).mockImplementation(((cmd: string, args?: Record<string, unknown>) => {
      calls.push({ cmd, args });
      if (cmd === "list_local_projects") {
        return Promise.resolve([
          // Legacy hub: no .title sidecar (title was de-slugged from the key) — the backfill target.
          { key: "acme-crm", title: "Acme Crm", hasPlan: true, updatedAt: 5, published: true, titled: false },
          // User-titled hub: .title present — must NEVER be stomped by the board title.
          { key: "other-app", title: "My Own Name", hasPlan: true, updatedAt: 5, published: true, titled: true },
        ]);
      }
      if (cmd === "github_graphql") {
        return Promise.resolve({ viewer: { projectsV2: { nodes: [
          GH_ACME,
          { ...GH_ACME, id: "PVT_2", number: 2, title: "Other App" },
        ] } } });
      }
      return Promise.resolve(null);
    }) as unknown as typeof invoke);
    render(<ProjectsList />);

    await screen.findByText("Acme CRM");
    // The derived-title hub matched board "Acme CRM" by key → its real title is persisted…
    await waitFor(() => {
      const set = calls.filter((c) => c.cmd === "set_project_title");
      expect(set).toHaveLength(1);
      expect(set[0].args).toMatchObject({ projectKey: "acme-crm", title: "Acme CRM" });
    });
    // …and the user-titled hub was not touched (exactly the one backfill call above).
  });
});

describe("ProjectsList — the list header (#3854)", () => {
  beforeEach(() => {
    vi.mocked(invoke).mockReset();
    useAppStore.setState({ activeWorkspace: "projects", githubToken: "", localDraftProjects: {}, githubState: null });
    routeInvoke([]);
